// Guardias de ARGOS Mecánico (Eje, 20-nov-2026). Mismo texto se inyecta en n8n.
// --- 1) Error externo (para «¿Error externo?» en el flujo principal)
function esErrorExterno(e) {
  const t = ((e.error_message || '') + ' ' + (e.error_stack || '')).toLowerCase();
  const patrones = ['gateway timed out', 'gateway timeout', 'bad gateway', 'service unavailable', 'temporarily unavailable',
    'too big', 'too large', 'file size', 'payload too large', 'quota', 'rate limit', 'too many requests',
    'econnreset', 'etimedout', 'econnrefused', 'enotfound', 'socket hang up', 'timed out', 'timeout',
    'insufficient', 'credit balance', 'billing', 'status code 429', 'status code 502', 'status code 503', 'status code 504'];
  return patrones.find(p => t.includes(p)) || null;
}

// --- 2) y 3) Revisión del cambio (para «Aplicar Cambio (merge)» en el subflujo)
function saltoEnExpresion(v) {
  if (typeof v === 'string') {
    if (!v.startsWith('=')) return false;
    return v.split('{{').slice(1).some(seg => seg.split('}}')[0].includes('\n'));
  }
  if (Array.isArray(v)) return v.some(saltoEnExpresion);
  if (v && typeof v === 'object') return Object.values(v).some(saltoEnExpresion);
  return false;
}
function vacio(v) { return v === undefined || v === null || v === '' || (typeof v === 'object' && Object.keys(v).length === 0); }
function revisarCambio(viejo, nuevo, versiones, ahoraMs) {
  if (!nuevo || typeof nuevo !== 'object' || Array.isArray(nuevo)) return 'node_parameters debe ser un objeto.';
  const borrados = Object.keys(viejo || {}).filter(k => !vacio(viejo[k]) && !(k in nuevo));
  if (borrados.length) return 'El cambio borra parámetros que existían (' + borrados.join(', ') + '). Requiere revisión humana.';
  for (const k of ['resource', 'operation']) {
    if (viejo && k in viejo && nuevo[k] !== viejo[k]) return 'El cambio modifica «' + k + '» (' + viejo[k] + ' → ' + nuevo[k] + '): es un cambio de diseño, no de configuración. Requiere revisión humana.';
  }
  if (saltoEnExpresion(nuevo)) return 'El cambio deja un salto de línea real dentro de {{ }} (usar \\n). No se aplica.';
  if (!Array.isArray(versiones)) return 'No se pudo leer el historial de versiones del flujo; por seguridad no se aplica.';
  const seisHoras = 6 * 3600 * 1000;
  const recientes = versiones.filter(v => ahoraMs - Date.parse(v.createdAt) < seisHoras).length;
  if (recientes >= 3) return 'El flujo ya tuvo ' + recientes + ' cambios en las últimas 6 h: tope de ARGOS Mecánico. Requiere revisión humana.';
  return null;
}


const real = $('Leer Workflow Real').first().json;
const _hist = $input.first().json || {};
const _versiones = Array.isArray(_hist.data) ? _hist.data : null;
const trigger = $('Execute Workflow Trigger').first().json;
const node_name = trigger.node_name;
let node_parameters = trigger.node_parameters;
if (typeof node_parameters === 'string') {
  try { node_parameters = JSON.parse(node_parameters); } catch (e) {
    return [{ json: { found: false, workflow_id: trigger.workflow_id, node_name, error: 'node_parameters no es JSON valido: ' + e.message } }];
  }
}
const workflow_id = trigger.workflow_id;
const _viejo = ((real.nodes || []).find(n => n.name === node_name) || {}).parameters;
if (_viejo) {
  const _motivo = revisarCambio(_viejo, node_parameters, _versiones, Date.now());
  if (_motivo) { return [{ json: { found: false, guardia: true, workflow_id, node_name, error: 'ARGOS (guardia): ' + _motivo } }]; }
}

const SETTINGS_WHITELIST = ['saveDataErrorExecution','saveDataSuccessExecution','saveManualExecutions','saveExecutionProgress','executionTimeout','timezone','errorWorkflow','executionOrder'];

let found = false;
const nodes = (real.nodes || []).map(n => {
  if (n.name === node_name) {
    found = true;
    return { ...n, parameters: node_parameters };
  }
  return n;
});

const settings = {};
for (const key of SETTINGS_WHITELIST) {
  if (real.settings && Object.prototype.hasOwnProperty.call(real.settings, key)) {
    settings[key] = real.settings[key];
  }
}

return [{ json: {
  found,
  workflow_id,
  node_name,
  nodeCountBefore: (real.nodes || []).length,
  nodeCountAfter: nodes.length,
  body: { name: real.name, nodes, connections: real.connections, settings }
} }];
